use gh0st_chess_protocol::{receipt::*, *};

fn bytes<const N: usize>(hex: &str) -> [u8; N] {
    let hex = hex.strip_prefix("0x").unwrap_or(hex);
    assert_eq!(hex.len(), N * 2);
    std::array::from_fn(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
}

#[test]
fn eip712_matches_the_independent_ethers_and_solidity_vector() {
    // Exact local fixture generated by evm/test-local.mjs -> evm/receipt-test-vector.json.
    // It uses chain 31337 and a mock vault, not a deployment address or production signing key.
    let domain = ReceiptDomain {
        chain_id: 31337,
        verifying_contract: bytes("5FC8d32690cc91D4c39d9d3abcBD16989F875707"),
    };
    let mut nonce = [0; 32];
    nonce[31] = 1;
    let receipt = ResultReceipt {
        material: ResultMaterial {
            game_id: bytes("1703c38980fc56ebf64029641d11bc13419ec701fc2471100072fb91dee9f38f"),
            player: bytes("70997970C51812dc3A010C7d01b50e0d17dc79C8"),
            principal_hash: bytes(
                "ca8eb856d33d8600b73aa767bcf8aa7fd7ad20be467c9ee59e9a1c9f97e50dde",
            ),
            nonce,
            final_position_hash: bytes(
                "bf361d20bf60c02309afafd9e1f56868b0820cd9de41d9f5ee9e495e97b3713f",
            ),
            transcript_hash: bytes(
                "772919d9e9f3637111d2de9cf6fae5f2895fcd9210f2676ff714461e6f4243a2",
            ),
            result: 1,
            engine_config_hash: bytes(
                "449218ea17561b58681938bc989c0da3c8e6ebf7145af84548b56ddcec87a492",
            ),
            completed_at: 1767225615,
        },
        issued_at: 1767225615,
        valid_until: 1767916815,
    };
    assert_eq!(
        keccak(RESULT_TYPE.as_bytes()),
        bytes("ad0dc778d3c25c1a8fb75b10ad61ce567382931d16b10e951148f2948ef255aa")
    );
    assert_eq!(
        domain.separator(),
        bytes("ff8acba9eb20f9598f2d21e8ba0b0bc2f820d17263ad396095ecafb3ac63e261")
    );
    assert_eq!(
        receipt.digest(&domain),
        bytes("f52eac27868613a6a8e1cc7443f18a22382c38661321cc1ac9cff15875a77ae0")
    );
    assert_eq!(
        evm_game_id(
            domain.chain_id,
            domain.verifying_contract,
            receipt.material.player,
            nonce
        ),
        receipt.material.game_id
    );
}

#[test]
fn uint256_nonce_and_domain_are_not_truncated() {
    let vault = [2; 20];
    let player = [3; 20];
    let mut low = [0; 32];
    low[31] = 1;
    let mut high = low;
    high[0] = 1;
    assert_ne!(
        evm_game_id(4663, vault, player, low),
        evm_game_id(4663, vault, player, high)
    );
    assert_ne!(
        evm_game_id(4663, vault, player, low),
        evm_game_id(31337, vault, player, low)
    );
    assert_ne!(
        evm_game_id(4663, vault, player, low),
        evm_game_id(4663, [4; 20], player, low)
    );
}
